import { useInterval } from '@cetus/hooks'
import useRpcConfigStore from '@cetus/stores/src/useRpcConfigStore'
import { useCallback, useEffect, useMemo, useRef } from 'react'

export function useRpcWorker() {
  const workerRef = useRef<Worker | null>(null)
  const { setRpcSpeed, nodes } = useRpcConfigStore()

  const rpcLinks = useMemo(() => nodes.filter(rpc => rpc.link.length > 0).map(rpc => rpc.link), [nodes])

  const handleWorkerMessage = useCallback(
    (event: MessageEvent<Record<string, number>>) => {
      if (event.data?.error) {
        console.error('useRpcWorker worker onmessage error', event.data.error)
        setRpcSpeed({})
        return
      }

      if (event?.data) {
        console.log('1111###🚀 ~ useRpcWorker ~ event.data:', event.data)
        setRpcSpeed(event.data)
      } else {
        setRpcSpeed({})
      }
    },
    [setRpcSpeed]
  )

  const startTestRpc = useCallback(() => {
    if (rpcLinks.length === 0 || typeof window === 'undefined') {
      return
    }

    if (!workerRef.current) {
      workerRef.current = new Worker('/worker/rpc.worker.js')
      workerRef.current.onmessage = handleWorkerMessage
      workerRef.current.onerror = error => {
        console.error('useRpcWorker worker onerror', error)
        setRpcSpeed({})
      }
    }

    workerRef.current.postMessage({
      rpcList: rpcLinks
    })
  }, [handleWorkerMessage, rpcLinks, setRpcSpeed])

  const { startTimer, stopTimer } = useInterval({
    interval: 5 * 1000,
    callback: () => {
      startTestRpc()
    }
  })

  useEffect(() => {
    if (rpcLinks.length === 0) {
      stopTimer()
      setRpcSpeed({})
      if (workerRef.current) {
        workerRef.current.terminate()
        workerRef.current = null
      }
      return
    }

    startTestRpc()
    startTimer()

    return () => {
      stopTimer()
    }
  }, [rpcLinks, setRpcSpeed, startTestRpc, startTimer, stopTimer])

  useEffect(() => {
    return () => {
      stopTimer()
      if (workerRef.current) {
        workerRef.current.terminate()
        workerRef.current = null
      }
    }
  }, [stopTimer])
}
